{
 "fields": {
  "unit": {
   "value": "patient_regimen",
   "evidence": [
    "article:p21",
    "article/Table 1"
   ],
   "explanation": "The study compares ex vivo drug responses of spheroids from 10 patients against their specific clinical treatment regimens. Each patient received different drugs, making the unit a combination of patient and regimen."
  },
  "platform": {
   "value": "perfused_chip",
   "evidence": [
    "article:p12",
    "article:p17"
   ],
   "explanation": "The article describes a 'fully 3D-printed microfluidic device' that sustains spheroids under 'flow conditions' (perfusion)."
  },
  "readout": {
   "value": "viability",
   "evidence": [
    "article:p21",
    "article:p51"
   ],
   "explanation": "The primary metric reported for correlation with clinical outcomes is the 'reduction in viability' measured by WST1 assay."
  },
  "direction": {
   "value": "higher_sensitive",
   "evidence": [
    "article:p21"
   ],
   "explanation": "The reported metric is 'viability reduction'. A higher reduction (e.g., 0.90) indicates greater sensitivity/response. Text states T1 had ~90% reduction and responded clinically."
  },
  "threshold_rule": {
   "value": "no_binary_rule",
   "evidence": [
    "article:p59"
   ],
   "explanation": "The authors report 'compelling correlations' and 'positive trends' but do not define a specific numeric cutoff or binary classification rule for predicting response in the text or tables provided."
  },
  "threshold_timing": {
   "value": "not_reported",
   "evidence": [
    "article:p21",
    "article:p59"
   ],
   "explanation": "No threshold optimization process or prespecified cutoff is described."
  },
  "patient_mapping": {
   "value": "individual_available",
   "evidence": [
    "article/Table 1",
    "supp/Fig. 5/B2"
   ],
   "explanation": "Table 1 provides individual patient clinical outcomes, and Supplementary Figure 5 provides individual ex vivo viability data for each tissue/patient."
  },
  "regimen_match": {
   "value": "partial",
   "evidence": [
    "article:p21",
    "article/Table 1"
   ],
   "explanation": "The ex vivo tests used single agents or simple combinations (e.g., Oxaliplatin, 5-FU) based on IC50, while clinical regimens were often complex multi-drug combinations (e.g., FOLFOX). The match is partial as the exact clinical cocktail was not always replicated ex vivo."
  },
  "n_units": {
   "value": 10,
   "evidence": [
    "article:p21",
    "article/Table 1"
   ],
   "explanation": "Tumor samples were collected from ten patients (T1-T10)."
  },
  "split": {
   "value": "same_cohort",
   "evidence": [
    "article:p21",
    "article:p59"
   ],
   "explanation": "The correlation analysis was performed on the same set of 10 patients used to generate the ex vivo data; there is no independent test set mentioned."
  }
 },
